Load the cached values from `ITEMS` and the two target sheets. For each data row in `SHEET1` and `SHEET2`, replace column B with the corresponding stripped value from `ITEMS` column B. Save the workbook with plain values in the answer cells.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def find_sheet(wb_obj, name):
    if name in wb_obj.sheetnames:
        return wb_obj[name]
    low = name.lower()
    for sn in wb_obj.sheetnames:
        if sn.lower() == low:
            return wb_obj[sn]
    return wb_obj.create_sheet(name)

def clean_value(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def last_data_row(ws, max_col=2):
    last = 1
    for row in ws.iter_rows(min_row=2, max_col=max_col):
        if any(cell.value is not None for cell in row):
            last = row[0].row
    return last

items_ws = find_sheet(vals, "ITEMS")
items_last = last_data_row(items_ws)
items_values = []
for r in range(2, items_last + 1):
    items_values.append(clean_value(items_ws.cell(row=r, column=2).value))

for sheet_name in ("SHEET1", "SHEET2"):
    vws = find_sheet(vals, sheet_name)
    tws = find_sheet(wb, sheet_name)
    target_last = last_data_row(vws)

    for i, r in enumerate(range(2, target_last + 1)):
        if i < len(items_values):
            ref = items_values[i]
            tws.cell(row=r, column=2).value = ref
            print(sheet_name, r, repr(ref))
        else:
            print(sheet_name, r, "no ITEMS value, left unchanged")

wb.save(OUT)
